def note_to_int(note):
    """Convert notes in the form of C, C#, Cb, C##, etc. to an integer in the
    range of 0-11.

    Throw a NoteFormatError exception if the note format is not recognised.
    """
    if is_valid_note(note):
        val = _note_dict[note[0]]
    else:
        raise NoteFormatError("Unknown note format '%s'" % note)

    # Check for '#' and 'b' postfixes
    for post in note[1:]:
        if post == "b":
            val -= 1
        elif post == "#":
            val += 1
    return val % 12

def __int__(self):
    """Return the current octave multiplied by twelve and add
    notes.note_to_int to it.

    This means a C-0 returns 0, C-1 returns 12, etc. This method allows
    you to use int() on Notes.
    """
    res = self.octave * 12 + notes.note_to_int(self.name[0])
    for n in self.name[1:]:
        if n == "#":
            res += 1
        elif n == "b":
            res -= 1
    return res
